"""Fixed-byte compatibility tests for the three proof-bundle wire envelopes.

These tests anchor RegionProofBundle / ConvexPolygonProofBundle /
MerkleMultiProofBundle compatibility to byte strings captured from the
pre-refactor codec. The hex constants below are frozen output of the OLD
encoder; the refactored implementation must (1) emit exactly those bytes for
the same inputs, (2) decode those old bytes back to field-equal bundles, and
(3) keep the same verification verdict. Compatibility is therefore NOT
judged by a new-encoder/new-decoder round trip alone.
"""

import itertools
import unittest

from zkregion import (
    ConvexPolygonRegion,
    ConvexPolygonRegionProof,
    ConvexPolygonProofBundle,
    MerkleMultiProof,
    MerkleMultiProofBundle,
    PedersenCommitment,
    RangeProof,
    Region,
    RegionProof,
    RegionProofBundle,
    RegionWideProof,
    WideRangeProof,
    decode_convex_polygon_proof_bundle,
    decode_merkle_multi_proof_bundle,
    decode_region_proof_bundle,
    encode_convex_polygon_proof_bundle,
    encode_merkle_multi_proof_bundle,
    encode_region_proof_bundle,
    merkle_root,
    pedersen_commit,
    prove_convex_polygon,
    prove_multi_inclusion,
    prove_region,
    prove_region_wide,
    verify_convex_polygon_proof_bundle,
    verify_merkle_multi_proof_bundle,
    verify_region_proof_bundle,
)

SMALL_PRIME = 104729


def counter_randbelow(start=1):
    counter = itertools.count(start)

    def _randbelow(n):
        return next(counter) % max(1, n)

    return _randbelow


class DetRand:
    def __init__(self):
        self.n = 0

    def __call__(self, n):
        self.n += 1
        return (self.n * 7 + 3) % max(1, n)


